 "content": "def transform(grid):
    """Connect consecutive occurrences of the marker color in each row and column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The sparse marker color is the most common non-background color.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    candidates = [v for v in counts if v != background]
    marker = max(candidates, key=lambda v: counts[v])
    paint = 3
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = paint
